import fs from 'node:fs';
import { canonicalCountry } from '../src/country-selection.mjs';
import { hasDescribedPhoto } from '../src/beer-photo-eligibility.mjs';
const catalog=JSON.parse(fs.readFileSync('public/data/catalog.json'));const map=JSON.parse(fs.readFileSync('public/maps/world-50m.geojson'));
const breweries=new Map(catalog.breweries.map(b=>[b.id,b]));const stats=new Map();
for(const beer of catalog.beers){const b=breweries.get(beer.breweryId);const name=canonicalCountry(b?.country);const s=stats.get(name)||{records:0,describedPhotos:0,mapReady:0};s.records++;if(hasDescribedPhoto(beer))s.describedPhotos++;if(hasDescribedPhoto(beer)&&b?.locationVerified&&Number.isFinite(b.lat)&&Number.isFinite(b.lng))s.mapReady++;stats.set(name,s)}
const special=new Set(['Antarctica','S. Geo. and the Is.','Heard I. and McDonald Is.','Fr. S. Antarctic Lands','Indian Ocean Ter.','Ashmore and Cartier Is.','Coral Sea Is.','Spratly Is.','Clipperton I.','U.S. Minor Outlying Is.']);
const rows=map.features.map(f=>{const country=canonicalCountry(f.properties.name);const s=stats.get(country)||{records:0,describedPhotos:0,mapReady:0};return {mapFeatureName:f.properties.name,country,...s,gap:s.mapReady?'has_map_ready_products':s.records?'catalogue_without_map_ready_packshot':'no_catalogue_records',scopeNote:special.has(f.properties.name)?'remote_uninhabited_or_antarctic_map_territory_not_ordinary_beer_country':null}}).sort((a,b)=>a.country.localeCompare(b.country));
const out={createdAt:'2026-10-02',baselineCatalogBeers:catalog.beers.length,mapSource:'public/maps/world-50m.geojson',features:rows.length,scope:'Natural Earth map countries/territories; NOT a list of sovereign states or a claim that beer is produced everywhere.',classificationRule:'country aliases use the product canonicalCountry function; map readiness requires an actual image, a nonempty product description, and verified finite brewery reference coordinates. Geographic bottle fit and photo deduplication are separate UI conditions.',summary:Object.fromEntries(['has_map_ready_products','catalogue_without_map_ready_packshot','no_catalogue_records'].map(k=>[k,rows.filter(r=>r.gap===k).length])),rows};
fs.writeFileSync('research/award-country-expansion-2026-10-02/map-country-gaps.json',JSON.stringify(out,null,2)+'\n');console.log(out.summary);
